window.COURSE_SEARCH_INDEX = [{"title": "Announcements & deadlines", "page": "CPS 2231: Computer Programming", "href": "index.html#announcements", "text": "Announcements & deadlines Course announcements, assignment deadlines and examination details are posted on Canvas (opens in a new tab) . Use the schedule page for confirmed class meeting times."}, {"title": "Course overview", "page": "CPS 2231: Computer Programming", "href": "index.html#overview", "text": "Course overview Fundamental concepts and techniques of computer programming using a high-level, object-oriented programming language. Topics include problem solving, algorithm design, arrays, searching and sorting, classes and objects, encapsulation, inheritance and polymorphism, exception handling, file input and output, abstract classes and interfaces, recursion, and the use of systems software. Prerequisite: CPS 1231. See the syllabus summary for learning outcomes, course expectations and student support."}, {"title": "Learning objectives", "page": "CPS 2231: Computer Programming", "href": "index.html#outcomes", "text": "Learning objectives Upon successful completion of the course, you will be able to: Define and describe computing and programming concepts. Implement a computing-based solution using appropriate programming constructs. Apply a problem-solving process and design algorithms. Design, code, execute, test, debug and document programs in a high-level, object-oriented language."}, {"title": "Course topics", "page": "CPS 2231: Computer Programming", "href": "index.html#topics", "text": "Course topics Problem solving and algorithm design Arrays, searching and sorting Classes, objects and encapsulation Inheritance and polymorphism Abstract classes and interfaces Exception handling File input and output Recursion and systems software"}, {"title": "Teaching team", "page": "CPS 2231: Computer Programming", "href": "index.html#teaching-team", "text": "Teaching team Name Role Email Dr. Y. Tiffany Tang Instructor yatang@kean.edu Dr. Pinata Winoto Instructor pwinoto@kean.edu Songlin Shang Teaching assistant shangs@kean.edu Cong Ye Teaching assistant yecon@kean.edu Zike Deng Teaching assistant baylordeng@connect.hku.hk See office hours and contact information for availability. Please use your Kean email account when contacting an instructor."}, {"title": "Course information", "page": "Course syllabus", "href": "syllabus.html#course-information", "text": "The essentials Course information Course CPS 2231 · Computer Programming Credits 4 credit hours Term & sections Spring 2025 · Sections 02 & 09 Prerequisite CPS 1231 Class meetings Monday & Wednesday, 8:30–10:15 a.m. Location Gehekai Hall, Room C103 Campus Wenzhou-Kean University"}, {"title": "Course description", "page": "Course syllabus", "href": "syllabus.html#description", "text": "Course description Course description Fundamental concepts and techniques of computer programming using a high-level, object-oriented programming language. The course develops problem-solving skills, algorithm design and the use of systems software. Topics include arrays, searching and sorting, classes and objects, encapsulation, inheritance and polymorphism, exception handling, file input and output, abstract classes and interfaces, and recursion."}, {"title": "Learning outcomes", "page": "Course syllabus", "href": "syllabus.html#learning-outcomes", "text": "Student learning outcomes Learning outcomes Define and describe computing and programming concepts. Implement a computing-based solution to meet a given set of computing constructs. Demonstrate an understanding of problem-solving processes and design algorithms. Design, code, execute, test, debug and document programs in a high-level, object-oriented programming language."}, {"title": "Assignments and grading", "page": "Course syllabus", "href": "syllabus.html#assessment", "text": "Coursework & feedback Assignments and grading Canvas is the course learning management system for announcements, assignments, course materials and the digital gradebook. Review assignment instructions and feedback there throughout the semester. Refer to the instructor’s full syllabus, Canvas announcements and assignment instructions for grading weights, examination dates and submission deadlines. Open the course on Canvas (opens in a new tab)"}, {"title": "Course policies", "page": "Course syllabus", "href": "syllabus.html#policies", "text": "Academic expectations Course policies Supplemental Instruction (SI) The syllabus requires students in CPS 1231/2231 to attend at least 7 SI sessions during the semester, including 3 within the first 3 weeks . Book an appointment in TutorTrac before attending; attendance is recorded there. SI appointment guidance (opens in a new tab) Academic integrity & generative AI AI-generated content must not be presented as original student work. Where the instructor permits AI use, acknowledge and cite it, and take responsibility for the accuracy and appropriateness of submitted work. Follow any additional assignment-specific rules. University academic integrity policy (opens in a new tab) Course materials & intellectual property The syllabus limits class materials to the personal use of registered students during the semester. Do not publicly post or distribute homework, programs or other classwork. Follow the instructor’s permissions for each resource. Communication & technology Use a valid Kean email account when contacting your instructor, and check Canvas regularly. For account or technology issues, contact ithelpdesk@wku.edu.cn . Accessibility & accommodations Students who need instructional accommodations should notify the instructor as soon as possible and no later than the second week of the term. Contact oas@wku.edu.cn to discuss special needs and arrangements."}, {"title": "Student support", "page": "Course syllabus", "href": "syllabus.html#student-support", "text": "Learning support Student support Academic support: contact sasrc@wku.edu.cn for academic advising, peer tutoring and learning workshops. English Language Center: contact elc@wku.edu.cn for support with English. Course questions: meet the teaching team during office hours or email using your Kean account."}, {"title": "Class meetings", "page": "Course schedule", "href": "calendar.html", "text": "Weekly class meetings Class meetings Spring 2025 · Sections 02 & 09 · All times in China Standard Time (UTC+8) Day Time Location Monday 8:30–10:15 a.m. Gehekai Hall Room C103 Wednesday 8:30–10:15 a.m. Gehekai Hall Room C103 The syllabus lists two consecutive class blocks: 8:30–9:15 a.m. and 9:15–10:15 a.m. on Monday and Wednesday."}, {"title": "Assignments & examinations", "page": "Course schedule", "href": "calendar.html", "text": "Course deadlines Assignments & examinations Use Canvas for assignment release dates, submission deadlines, examination announcements and changes to the class schedule. Confirm the dates and requirements in your instructor’s course announcements. Check course announcements (opens in a new tab)"}, {"title": "Preparing for class", "page": "Course schedule", "href": "calendar.html", "text": "Each week Preparing for class Review assigned readings and materials before class. Practice with the available laboratory exercises . Bring questions and attempted solutions to office hours . Plan SI appointments in advance. The syllabus requires 7 sessions, including 3 within the first 3 weeks."}, {"title": "Calendar archive", "page": "Course schedule", "href": "calendar.html", "text": "Previous course material Calendar archive The original website contains a calendar dated 2024. It is retained for reference and does not set deadlines for Spring 2025. View the 2024 calendar archive"}, {"title": "Tutorial and laboratory materials", "page": "Laboratory materials", "href": "lab.html", "text": "Getting started tutorial. Lab 1, Lab 2, Lab 3, Lab 4, Lab 5, Lab 6. Programming exercises, PDF instructions and code quality guide."}, {"title": "Code quality guide", "page": "Laboratory materials", "href": "lab.html", "text": "Programming patterns, coding guidelines and code quality."}, {"title": "TA office hours", "page": "Office hours & contact", "href": "office-hours.html", "text": "Teaching assistant support TA office hours Please confirm availability. These TA hours are carried over from the original course website and are not specified in the supplied course syllabus. Monday and Wednesday overlap the listed class meeting times; email the TA before visiting. Existing TA schedule · China Standard Time (UTC+8) · Availability to be confirmed Day Time Teaching assistant Room Monday 8:30–10:30 a.m. Songlin Shang GHK C103 Tuesday 10–11 a.m. Cong Ye GHK C103 Wednesday 8:30–10:30 a.m. Songlin Shang GHK C103 Thursday 10–11 a.m. Cong Ye GHK C103 Friday No regular hours listed. Contact the teaching team."}, {"title": "Instructor contacts", "page": "Office hours & contact", "href": "office-hours.html", "text": "Get in touch Instructor contacts Contact your instructor directly to arrange a meeting. Use your Kean email address and include your course, section and a brief description of your question. Dr. Y. Tiffany Tang yatang@kean.edu Dr. Pinata Winoto pwinoto@kean.edu"}, {"title": "Preparing for office hours", "page": "Office hours & contact", "href": "office-hours.html", "text": "Before your visit Preparing for office hours Identify the concept or part of the assignment you would like to discuss. Bring your current code and the exact error or unexpected result. Be ready to explain the approaches you have already tried."}, {"title": "Course materials on GitHub", "page": "Laboratory materials", "href": "lab.html#course-materials", "text": "Java source code, lab PDFs, practice exercises, lab discussion notes and troubleshooting resources in the course GitHub repository."}];
